#!/usr/bin/env python3
"""Compare substitution methods through parity signatures."""
from typing import Sequence
State = tuple[bool, ...]

def signature(n: int, method: Sequence[int]) -> State:
    out = [False] * n
    for i in method:
        if not 0 <= i < n: raise ValueError("invalid coordinate")
        out[i] = not out[i]
    return tuple(out)

def endpoint(state: State, method: Sequence[int]) -> State:
    sig = signature(len(state), method)
    return tuple(x != y for x, y in zip(state, sig))

def main() -> None:
    start = (False, True, False, False)
    p = (0, 1, 2, 1, 3, 0)
    q = (2, 3)
    print("signature(p):", signature(4, p))
    print("signature(q):", signature(4, q))
    print("endpoint(p): ", endpoint(start, p))
    print("endpoint(q): ", endpoint(start, q))
    assert signature(4, p) == signature(4, q)
    assert endpoint(start, p) == endpoint(start, q)
if __name__ == "__main__":
    main()

