"""Demonstrate commuting squares, cancellation, and reversal loops."""
from typing import Sequence
State = tuple[bool, ...]

def follow(state: State, method: Sequence[int]) -> State:
    out = list(state)
    for i in method:
        if not 0 <= i < len(out): raise ValueError("invalid coordinate")
        out[i] = not out[i]
    return tuple(out)

def main() -> None:
    r = (False, True, False)
    assert follow(r, (0, 2)) == follow(r, (2, 0))
    assert follow(r, (1, 1)) == r
    p = (0, 1, 2, 1)
    loop = p + tuple(reversed(p))
    assert follow(r, loop) == r
    print("square endpoint:", follow(r, (0, 2)))
    print("backtrack endpoint:", follow(r, (1, 1)))
    print("reversal-loop endpoint:", follow(r, loop))
if __name__ == "__main__":
    main()

