from typing import Sequence

def parity_signature(dimension: int, method: Sequence[int]) -> tuple[bool, ...]:
    """Compute the odd-occurrence vector in O(len(method)) time."""
    if dimension < 0: raise ValueError("negative dimension")
    parity = [False] * dimension
    for coordinate in method:
        if not 0 <= coordinate < dimension: raise ValueError("invalid coordinate")
        parity[coordinate] = not parity[coordinate]
    return tuple(parity)

from typing import Sequence
State = tuple[bool, ...]

def endpoint_by_signature(state: State, method: Sequence[int]) -> State:
    """Evaluate a method by XOR with its parity signature."""
    parity = [False] * len(state)
    for coordinate in method:
        if not 0 <= coordinate < len(state): raise ValueError("invalid coordinate")
        parity[coordinate] = not parity[coordinate]
    return tuple(value != bit for value, bit in zip(state, parity))

from typing import Sequence

def canonical_endpoint_representative(dimension: int, method: Sequence[int]) -> tuple[int, ...]:
    """Return the increasing shortest method with the same endpoint action."""
    parity = [False] * dimension
    for coordinate in method:
        if not 0 <= coordinate < dimension: raise ValueError("invalid coordinate")
        parity[coordinate] = not parity[coordinate]
    return tuple(i for i, odd in enumerate(parity) if odd)

